CREATE POLICY "Upload own market media" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='market-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Read own market media" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='market-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Delete own market media" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='market-media' AND (storage.foldername(name))[1]=auth.uid()::text);